// NEW independent V23 acquisition file-only reader proposal.
// Recompute all raw hashes, canonical base64, gzip roundtrips and packed latest SAVE.
// Copy every formal top-level boolean and structured fact verbatim; never define outcome or HD success.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {createGunzip} from 'node:zlib';
import {Writable,Readable} from 'node:stream';
import {pipeline} from 'node:stream/promises';
import {fileURLToPath} from 'node:url';
import {verifyOriginalSavePair} from '../../scripts/hd-mobile-system-runtime-oracle.mjs';
const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..'),HARD=30*1024*1024;
const sha=b=>createHash('sha256').update(b).digest('hex'),parse=b=>JSON.parse(b.toString('utf8').replace(/^\uFEFF/,''));
function safe(name){assert.ok(typeof name==='string'&&name.length&&!name.includes('\\')&&!path.isAbsolute(name)&&!name.split('/').includes('..'));const abs=path.resolve(ROOT,name),rel=path.relative(ROOT,abs);assert.ok(rel&&!rel.startsWith('..'+path.sep)&&rel!=='..'&&!path.isAbsolute(rel));return abs;}
function pin(p){assert.ok(p&&Number.isSafeInteger(p.bytes)&&p.bytes>=0&&/^[0-9a-f]{64}$/.test(p.sha256));const b=fs.readFileSync(safe(p.path));assert.equal(b.length,p.bytes,p.path);assert.equal(sha(b),p.sha256,p.path);return b;}
function at(v,ks){for(const k of ks){assert.ok(v&&Object.hasOwn(v,k));v=v[k];}return v;}
const a=process.argv.slice(2);assert.ok(a.length===4||a.length===5&&a[4]==='--reopen-named','Use --canonical <path> --canonical-sha256 <hash> [--reopen-named]');assert.equal(a[0],'--canonical');assert.equal(a[2],'--canonical-sha256');assert.match(a[3],/^[0-9a-f]{64}$/);
const cb=fs.readFileSync(safe(a[1]));assert.equal(sha(cb),a[3]);const C=parse(cb),I=parse(pin(C.archive));assert.equal(I.schemaVersion,2);assert.equal(I.kind,'named-gzip-raw-sha256-archive');assert.equal(I.namedFileArchiveClosed,true);assert.equal(I.portableClosedArchive,false);assert.equal(C.archive.namedFileArchiveClosed,true);assert.equal(C.archive.portableClosedArchive,false);
assert.equal(I.namedFiles.length,C.archive.namedFiles);assert.equal(I.uniqueBlobs,C.archive.uniqueBlobs);assert.equal(I.parts.length,C.archive.parts);assert.ok(Array.isArray(C.actualRuns)&&C.actualRuns.length===3);assert.deepEqual(C.actualRuns.map(r=>r.id),['v23','v24b','v24c']);assert.ok(Array.isArray(I.externalCommittedDependencies)&&I.externalCommittedDependencies.length>=1);assert.deepEqual(C.externalCommittedDependencies,I.externalCommittedDependencies);assert.ok(Array.isArray(I.rawResultsEmbeddedOnce));
const names=new Set(),needed=new Map();for(const p of I.namedFiles){safe(p.path);assert.ok(!names.has(p.path),'Unique named path');names.add(p.path);assert.ok(!p.path.split('/').some(x=>['private-browser-profile','cache'].includes(x)));assert.ok(!I.excludedHistoricalBlobs.some(x=>x.path===p.path||x.sha256===p.sha256),'Historical full raw/parts stay external');assert.ok(!/docs\/validation\/.*-archive(?:-part\d+)?\.json$/.test(p.path));assert.ok(!/impact13-battle-actual-v(?:15|16b|17|18|19|20|21|22)\/result\.json$/.test(p.path));if(needed.has(p.sha256))assert.equal(needed.get(p.sha256),p.bytes);else needed.set(p.sha256,p.bytes);}
const smallNeeded=new Set([...C.actualRuns.flatMap(r=>[r.latestWorld.sha256,r.rootProof.sha256,...r.latestPair.map(p=>p.sha256)]),...(C.independentMoviePixelProof?[C.independentMoviePixelProof.sha256]:[])]),small=new Map(),seen=new Map(),partNames=new Set();
for(const p of I.parts){assert.ok(!partNames.has(p.path));partNames.add(p.path);assert.ok(p.bytes<HARD,'Every part strictly below30MiB');const part=parse(pin(p));assert.equal(part.schemaVersion,2);assert.equal(Object.keys(part.blobs).length,p.blobs);
 for(const [h,e]of Object.entries(part.blobs)){assert.match(h,/^[0-9a-f]{64}$/);assert.ok(!seen.has(h),'Each raw blob occurs in one part only');assert.ok(needed.has(h),'No unreferenced archive blob');assert.equal(e.sha256,h);assert.equal(e.bytes,needed.get(h));assert.equal(e.encoding,'gzip+base64');assert.equal(typeof e.data,'string');assert.equal(e.data.length%4,0,'Canonical base64 length');const gz=Buffer.from(e.data,'base64');assert.equal(gz.toString('base64'),e.data,'Exact canonical base64: reject every invalid character, padding or truncated decode');assert.equal(gz.length,e.gzipBytes);assert.equal(sha(gz),e.gzipSha256);let n=0;const rh=createHash('sha256'),chunks=[];await pipeline(Readable.from(gz),createGunzip(),new Writable({write(c,enc,done){n+=c.length;rh.update(c);if(smallNeeded.has(h)){assert.ok(n<4*1024*1024);chunks.push(c);}done();}}));assert.equal(n,e.bytes);assert.equal(rh.digest('hex'),h);seen.set(h,n);if(smallNeeded.has(h))small.set(h,Buffer.concat(chunks));
 }
}
assert.equal(seen.size,I.uniqueBlobs);assert.equal(seen.size,needed.size);for(const h of needed.keys())assert.ok(seen.has(h),'Every named file has its raw blob');
const namedByPath=new Map(I.namedFiles.map(p=>[p.path,p]));
assert.deepEqual(I.rawResultsEmbeddedOnce,C.actualRuns.filter(r=>r.result!==null).map(r=>({id:r.id,...r.result})));assert.deepEqual(I.missingAggregateResultRunIds,C.actualRuns.filter(r=>r.result===null).map(r=>r.id));assert.equal(I.rawResultEmbeddedOnce,I.rawResultsEmbeddedOnce.length>0);
for(const r of C.actualRuns){assert.equal(r.actualDirectory,{'v23':'build/impact-skill-20261014/impact13-battle-actual-v23','v24b':'build/impact-skill-20261014/impact13-battle-actual-v24','v24c':'build/impact-skill-20261014/impact13-battle-actual-v24c'}[r.id]);assert.ok(Object.hasOwn(r,'result'));if(r.result!==null){assert.deepEqual(namedByPath.get(r.result.path),r.result);assert.ok(seen.has(r.result.sha256));}else assert.ok(!I.namedFiles.some(p=>p.path.startsWith(r.actualDirectory+'/')&&path.basename(p.path)==='result.json'),'No placeholder result in recovered failed run');assert.deepEqual(namedByPath.get(r.rootProof.path),r.rootProof);assert.deepEqual(namedByPath.get(r.rootVerifier.path),r.rootVerifier);assert.deepEqual(namedByPath.get(r.latestWorld.path),r.latestWorld);const proof=parse(small.get(r.rootProof.sha256)),w=parse(small.get(r.latestWorld.sha256));assert.deepEqual(proof.verifier,r.rootVerifier);assert.deepEqual(proof.tool,r.expectedCandidate);assert.deepEqual(namedByPath.get(r.expectedCandidate.path),r.expectedCandidate);assert.deepEqual(at(proof,r.proofPaths.terminal),r.terminal);assert.deepEqual(at(proof,r.proofPaths.result),r.result);assert.deepEqual(at(proof,r.proofPaths.latestWorld),r.latestWorld);assert.deepEqual(at(proof,r.proofPaths.latestPair),r.latestPair);assert.equal(sha(Buffer.from(JSON.stringify(w))),r.worldJsonSha256);assert.equal(at(proof,r.proofPaths.publicSaves).length,r.publicSaveCount);assert.equal(at(proof,r.proofPaths.latestPublicSave),r.latestPublicSave);assert.equal(at(proof,r.proofPaths.latestSlot),r.latestSlot);if(r.publicSaveCount){assert.equal(r.latestIsPriorInput,false);assert.deepEqual(at(proof,r.proofPaths.publicSaves).at(-1).pair,r.latestPair);}else{assert.equal(r.latestIsPriorInput,true);assert.equal(r.latestWorld.bytes,C.currentSavedInput.world.bytes);assert.equal(r.latestWorld.sha256,C.currentSavedInput.world.sha256);assert.equal(r.worldJsonSha256,C.currentSavedInput.worldJsonSha256);assert.deepEqual(r.latestPair,C.currentSavedInput.pair);assert.equal(r.latestPublicSave,C.currentSavedInput.tag);assert.equal(r.latestSlot,C.currentSavedInput.slot);}for(const cp of at(proof,r.proofPaths.publicSaves))for(const p of cp.pair){assert.deepEqual(namedByPath.get(p.path),p);assert.equal(seen.get(p.sha256),p.bytes);}assert.deepEqual(r.facts,proof,'Each actual run retains every independent receipt field');for(const[k,v]of Object.entries(r.facts))assert.deepEqual(proof[k],v);for(const p of r.latestPair)assert.deepEqual(namedByPath.get(p.path),p);assert.equal(verifyOriginalSavePair({sav0:small.get(r.latestPair[0].sha256).toString('hex'),sav1:small.get(r.latestPair[1].sha256).toString('hex'),world:w,lib:'libs/dat-mod.lib',identity:'v1:414390:1d36da77:1e9c0477'}).ok,true);}
const last=C.actualRuns.at(-1),latestProof=parse(small.get(last.rootProof.sha256));assert.deepEqual(last.expectedCandidate,C.executedCandidate);assert.equal(C.actualRuns[0].facts.sourceRunAccepted,false);assert.equal(C.actualRuns[0].facts.aggregateObservationArraysPreserved,false);assert.equal(C.actualRuns[1].facts.sourceRunAccepted,false);assert.equal(C.actualRuns[1].publicSaveCount,0);assert.equal(C.actualRuns[1].latestIsPriorInput,true);for(const[k,v]of Object.entries(latestProof)){assert.ok(Object.hasOwn(C,k),'Canonical every formal field '+k);assert.deepEqual(C[k],v,'Canonical exact complete formal field '+k);}for(const key of ['sourceRunAccepted','actualCastOccurred','actualCastAccepted','actualMovieAccepted','actualPixelAccepted','actualPreparationAccepted','hd720VisualAccepted','hdAccepted','globalHdComplete','rngContinuityAccepted','sameRunContinuationAccepted'])if(Object.hasOwn(C,key)){assert.ok(Object.hasOwn(latestProof,key));assert.deepEqual(C[key],latestProof[key],'Canonical material flag '+key);}assert.deepEqual(C.independentTerminalFacts,Object.fromEntries(Object.entries(latestProof).filter(([,v])=>typeof v!=='boolean')),'Every independent structured fact is preserved exactly');for(const k of ['actualDamage','preparationDelta','latestDate','latestCaster','sourceCount','normalizedPhysicalSources','nativeSourceCount','nativeAggregate','latestPendingOrders'])if(Object.hasOwn(latestProof,k)&&Object.hasOwn(C,k))assert.deepEqual(C[k],latestProof[k],'Canonical structured fact '+k);const proofBooleans=Object.keys(latestProof).filter(k=>typeof latestProof[k]==='boolean').sort();assert.deepEqual(C.independentProofBooleanFields,proofBooleans);for(const k of proofBooleans)assert.deepEqual(C[k],latestProof[k],'Every independent proof boolean, no driver substitution');assert.deepEqual(C.latestActualRootProof,last.rootProof);assert.ok(last.publicSaveCount>=0&&last.publicSaveCount<=35);assert.deepEqual(C.independentMoviePixelProof,latestProof.moviePixelProof??null);assert.deepEqual(C.pixelAdapterSource,latestProof.pixelAdapterSource??null);for(const p of [C.independentMoviePixelProof,C.pixelAdapterSource])if(p!==null){assert.deepEqual(namedByPath.get(p.path),p);assert.equal(seen.get(p.sha256),p.bytes);}assert.equal(latestProof.sourceCount,C.sourceCount);assert.equal(latestProof.nativeSourceCount,128);assert.equal(latestProof.nativeAggregate,'713f2425551f3fbf3b9f0f892eeada969161c070c465e159f4126f1dd1944d9d');assert.equal(latestProof.normalizedPhysicalSources,C.normalizedPhysicalSources);assert.deepEqual(C.latestGenuineSave,{tag:last.latestPublicSave,slot:last.latestSlot,pair:last.latestPair,world:last.latestWorld,worldJsonSha256:last.worldJsonSha256});
if(a.length===5)for(const p of I.namedFiles){let n=0;const h=createHash('sha256');await pipeline(fs.createReadStream(safe(p.path)),new Writable({write(c,e,done){n+=c.length;h.update(c);done();}}));assert.equal(n,p.bytes,p.path);assert.equal(h.digest('hex'),p.sha256,p.path);}
console.log(JSON.stringify({ok:true,canonical:{path:a[1],bytes:cb.length,sha256:a[3]},namedFiles:I.namedFiles.length,uniqueBlobs:seen.size,parts:I.parts.length,allRawRoundtripsExact:true,allNamedBlobsClosed:true,noUnreferencedBlobs:true,rawResultsEmbeddedOnce:I.rawResultsEmbeddedOnce,latestPairsPackedAccepted:true,currentNamedDiskReopened:a.length===5,portableClosedArchive:false}));
